# -*- coding: utf-8 -*-
# one-time patch v44: 14 more abbreviations in the abbreviations tab, sw.js cache bump
import hashlib, json
b = open("index.html", "rb").read()
assert hashlib.sha256(b).hexdigest() == "8e13a55665181ff51eb007f887f5504eb78dc7a6d81ecd2f75d7cec7b35abe5a", "index.html is not the expected version"
h = b.decode("utf-8")
pairs = json.loads("[[\",{\\\"a\\\":\\\"כתי׳\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"כתהאריז״ל\\\",\\\"e\\\":\\\"כתבי האריז״ל (כתבי האר״י זכרונו לברכה)\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"כתי׳\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"כצ״ל\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"כ״ץ\\\",\\\"e\\\":\\\"כהן צדק\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"כצ״ל\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"שעה״כ\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"שעהיחוה״א\\\",\\\"e\\\":\\\"שער היחוד והאמונה\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"שעה״כ\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"חו״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"חוו״ד\\\",\\\"e\\\":\\\"חוות דעת\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"חו״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"אר״ש\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"ארצוה״ב\\\",\\\"e\\\":\\\"ארצות הברית\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"אר״ש\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"בה״ע\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"בהמק״ד\\\",\\\"e\\\":\\\"בית המקדש\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"בה״ע\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"עה״ק\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"עה״צ\\\",\\\"e\\\":\\\"על הציון\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"עה״ק\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"מוצש״ק\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"מוצ״ש\\\",\\\"e\\\":\\\"מוצאי שבת\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"מוצש״ק\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"ריב״ש\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"ריב״ק\\\",\\\"e\\\":\\\"רבי יהודה בן קלונימוס משפירא\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"ריב״ש\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"צלה״ק\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"צלה״ב\\\",\\\"e\\\":\\\"צריך להבין בזה\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"צלה״ק\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"מ״ע\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"מסנ״פ\\\",\\\"e\\\":\\\"מסירות נפש\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"מ״ע\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"אדומ״ו\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"אד״ו\\\",\\\"e\\\":\\\"ראשון, רביעי ושישי\\\",\\\"m\\\":\\\"(בכלל ״לא אד״ו ראש״) ראש השנה לעולם לא יחול בימים אלו.\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"אדומ״ו\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"נוק׳\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"נו״נ\\\",\\\"e\\\":\\\"נושא ונותן\\\",\\\"m\\\":\\\"אדם שתפקידו ללמוד ולדון בסוגיות הגמרא עם התלמידים ולענות על שאלותיהם.\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"נוק׳\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"ד״ז\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"דו״ש\\\",\\\"e\\\":\\\"דוברי שלום\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"ד״ז\\\",\\\"e\\\":\"], [\"עם הפיענוח שלהם (2,346).\", \"עם הפיענוח שלהם (2,360).\"]]")
for a, r in pairs:
    assert h.count(a) == 1, a
    h = h.replace(a, r)
out = h.encode("utf-8")
assert hashlib.sha256(out).hexdigest() == "07483d8e53192e5d985bd602ee642f8dabd29a1f3ee0b8361645ac7621a7085f", "patched index.html hash mismatch"
open("index.html", "wb").write(out)
sw = open("sw.js", encoding="utf-8").read()
old = 'const VERSION = "bar-hasaga-v43-abbr-round2b";'
assert sw.count(old) == 1
open("sw.js", "w", encoding="utf-8").write(sw.replace(old, 'const VERSION = "bar-hasaga-v44-abbr-round2c";'))
print("ok")
